// report.js — rt-v1.1 BATCH report renderer (ADR-074 backfill cron).
//
// A submission that arrived without its report gets one generated by the brain —
// unified into one document when several land together. Same structure as a
// sender-generated report (rt-v1.1, 01_META/report-template.md), same palette
// as report-medium.html, but honest about its own provenance: Agent R made this,
// not the submitter, because the standard was never skipped even when the
// report was missing (ADR-062: land, not-binding rows named; ADR-074: backfill
// covers only work that entered the router).
//
// Public API: renderBatchReport({ rows, generatedAt, origin }) -> HTML string.
// rows are transmission rows (see src/transmission.js): id, submitter, lane, kind,
// what, why, touches, screens, components, gaprefs, proof, grade, route, status,
// decision, decided_by, created_at — plus by_name/by_role when joined.

import { parseRefs, refChip } from "./refs.js";
import { RT_CSS, ROUTE, renderVerdictBanner, renderStampsSection, renderEventTrail, FOOTER_PROVENANCE } from "./rt.js";
import { esc, list, dateOnly, productEyebrow } from "./ui.js";
import { DEFAULT_BRAND } from "./tenant.js";
import { orgUrl } from "./orgpath.js";   // sprint 7, 7.4: every URL under the org of its address
import { BRAND_FONTS_LINK } from "./shell.js";

export function renderReportShell(title, inner) {
  return `<title>${esc(title)}</title>
${BRAND_FONTS_LINK}
<style>${RT_CSS}</style>
<div class="wrap">${inner}</div>`;
}

function thanksSentence(row) {
  const name = row.by_name || row.submitter || "contributor";
  const gapRefs = parseRefs(row.gaprefs ?? row.gapRefs);
  let tail;
  if (gapRefs.length) {
    tail = `this moves the gap${gapRefs.length > 1 ? "s" : ""} ${gapRefs.join(", ")}`;
  } else {
    const touches = list(row.touches).join(", ") || "the system";
    tail = `this lands in ${row.lane || "the ledger"} touching ${touches}`;
  }
  return `Thank you, ${esc(name)} — ${esc(tail)}.`;
}

function envelopeRow(k, v, mono) {
  if (v === undefined || v === null || String(v).trim() === "") return "";
  return `<div class="row"><span class="k">${esc(k)}</span><span class="v${mono ? " mono" : ""}">${esc(v)}</span></div>`;
}

function gapRefsBlock(row) {
  const refs = parseRefs(row.gaprefs ?? row.gapRefs);
  if (refs.length) {
    const chips = refs.map((r) => refChip(r, { className: "gapchip" })).join("");
    return `<div class="gapwrap">${chips}<div class="gapnote">these marks turn green on the next close.</div></div>`;
  }
  return `<div class="gapwrap"><div class="gapnote" style="color:var(--warn)">no gapRefs declared — this contribution closes nothing on the canvas until refs are attached (re-file with parent=${esc(row.id)}).</div></div>`;
}

function routeBanner(row) {
  return renderVerdictBanner(row);
}

function decisionBlock(row) {
  if (!row.decision) return "";
  const by = row.decided_by ? ` · decided by ${row.decided_by}` : "";
  return renderStampsSection([{ kind: row.decision, detail: `${row.decision}${by}` }], {
    icStyle: (tone) => `background:var(--${tone}bg);color:var(--${tone})`,
  });
}

const ROUTE_TRAIL_TONE = { good: "g", warn: "w", bad: "b" };

function trailLine(row) {
  const routeTone = ROUTE_TRAIL_TONE[(ROUTE[row.route] || ROUTE.incomplete).tone] || "b";
  const items = [
    { tone: "g", time: dateOnly(row.created_at), text: "recorded" },
    { tone: routeTone, time: dateOnly(row.created_at), text: `routed ${row.route || "—"}` },
  ];
  if (row.decision) items.push({ tone: "s", time: dateOnly(row.decided_at || row.created_at), text: `decision ${row.decision}${row.decided_by ? " · " + row.decided_by : ""}` });
  return renderEventTrail(items);
}

function renderRow(row, origin) {
  const id = String(row.id || "");
  const name = row.by_name || row.submitter || "";
  const role = row.by_role ? ` · ${esc(row.by_role)}` : "";
  const who = name ? `${esc(name)}${role}` : "unattributed";
  const link = origin ? `<a class="link" href="${esc(orgUrl(origin.replace(/\/$/, ""), "/contribution/" + id))}">view in ledger &rarr;</a>` : "";

  const envelope = [
    envelopeRow("what", row.what),
    envelopeRow("why", row.why),
    envelopeRow("touches", list(row.touches).join(", "), true),
    envelopeRow("screens", list(row.screens).join(", "), true),
    envelopeRow("components", list(row.components).join(", "), true),
    envelopeRow("proof", row.proof, true),
  ].join("");

  return `<section class="txn" id="${esc(id)}">
  <div class="ref">
    <div class="chips">
      <span class="chip mono">${esc(id)}</span>
      <span class="chip">lane: ${esc(row.lane || "—")}</span>
      <span class="chip">kind: ${esc(row.kind || "—")}</span>
      <span class="chip num">${esc(dateOnly(row.created_at))}</span>
      <span class="chip">${who}</span>
    </div>
    ${link}
  </div>
  <div class="thanks">${thanksSentence(row)}</div>
  <div class="card">${envelope || `<div class="row"><span class="v" style="color:var(--ink3)">no envelope fields declared</span></div>`}</div>
  ${gapRefsBlock(row)}
  ${routeBanner(row)}
  ${decisionBlock(row)}
  ${trailLine(row)}
</section>`;
}

export function renderBatchReport({ rows, generatedAt, origin, brand = DEFAULT_BRAND }) {
  const list_ = Array.isArray(rows) ? rows : [];
  const count = list_.length;
  const header = `<div class="eyebrow">${productEyebrow(brand)} — transmission reports (backfilled batch)</div>
  <h1>Backfilled Reports</h1>
  <div class="batch-meta num">generated ${esc(generatedAt)} · ${count} submission${count === 1 ? "" : "s"}</div>
  <p class="lede">These submissions arrived without their rt-v1.1 report. Per ADR-074 they were never blocked — and never escaped the standard: ${esc(brand.engine)} generated this batch. Sender-side generation remains the norm.</p>`;

  const sections = list_.map((row) => renderRow(row, origin)).join("\n");

  const footer = `<div class="foot">${FOOTER_PROVENANCE} · generated by ${esc(brand.engine)} · ADR-074${origin ? `<br>each section above is linked to its row at ${esc(orgUrl(origin.replace(/\/$/, ""), "/contribution/"))}&lt;id&gt;` : ""}</div>`;

  return renderReportShell("Backfilled Reports", `${header}\n${sections}\n${footer}`);
}
